package com.healthcompanion.ai; import java.util.*; import org.springframework.stereotype.Service;
@Service public class AiSafetyService {private static final List<String> BLOCKED=List.of("diagnose","diagnosis","diagnostic","do i have","have i got","is this cancer","do i suffer","what disease","prescribe","prescription","treatment plan","medication change","should i take","should i stop","diagnostiquer","est-ce que j'ai","ai-je","prescrire","traitement","médicament");public String safeQuestion(String question){var q=question==null?"":question.toLowerCase(Locale.ROOT);if(BLOCKED.stream().anyMatch(q::contains))return "The assistant cannot diagnose, prescribe, recommend treatment, or change medication. It can explain factual values and suggest discussing them with a healthcare professional.";return null;}}
